// spec: specs/catalog.md §12
// seed: tests/seed.admin.spec.ts
// catalog · кейсы cat-22, cat-23 (.qa/tests/catalog/) — #7b8b97e9 «מוצר אחד בכמה מקומות במחסן» (עבר QA 2026-10-12):
//   колонка «מיקום במחסן»: 3 строки, каждая начинается с кода места, + кнопка «+N» (меню со всеми местами);
//   строка / пункт меню открывает окно только своего места; «מקום היעד» — только места товара + «ללא מקום»;
//   окно удаления: «משויך ל-4 מקומות במחסן, ורשומות בהם עדיין 8.» и 4 строки (место с 0 тоже в списке).
// Товар «QA-AUTO-7b8b-M-<ts>» в 5 свободных «ריק» местах (найдены на карте во время прогона, шкафы F/G/E), остатки 5/2/1/0/0.
// ⚠️ 3 приёмки → 3 НЕУДАЛЯЕМЫЕ записи «קליטה» в יומן תנועות. Уборка — «הסרה מהמקום» во всех местах и удаление; места «ריק».
// Не запускать одновременно с inventory-lifecycle / order-lifecycle / cart-checkout (общие данные склада).
import { test, expect, Page } from '@playwright/test';
import * as H from '../inventory/_places';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const M = `QA-AUTO-7b8b-M-${TS}`;
const STOCK = [5, 2, 1, 0, 0];
const created = new Set<string>();
const used: H.Used = new Map();
let places: H.Place[] = [];

const plusBtn = (page: Page) => H.row(page, M).getByRole('button', { name: 'כל המקומות של המוצר' });
const menu = (page: Page) => page.getByRole('menu');

/** Строки колонки: текст «<код> | קומה 1 | ארון X | <полка>». */
async function rowCodes(page: Page): Promise<string[]> {
  const texts = (await H.locBtn(page, M).allInnerTexts()).map((t) => t.trim());
  return texts.map((t) => t.split(' | ')[0]);
}

test.describe('catalog — מוצר אחד בכמה מקומות במחסן (#7b8b97e9)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(400_000);
    await H.cleanup(browser, created, used);
  });

  test('5 מקומות: 3 שורות שכל אחת מתחילה בקוד המקום + «+2»; התפריט מציג את כל 5 (כולל «ללא כמות»), נסגר ב-Esc ובלחיצה בחוץ, אחרי רענון — אותו דבר #7b8b97e9 @desktop @data', async ({ page }) => {
    test.setTimeout(480_000);
    places = await H.pickEmptyPlaces(page, 5, ['F', 'G', 'E']);
    await H.createProduct(page, M, `QA7B8BM${TS}`, created);
    H.track(used, M, ...places);
    await H.bindPlace(page, M, places[0]);
    for (const pl of places.slice(1)) await H.bindPlace(page, M, pl, true);
    for (let i = 0; i < places.length; i++) if (STOCK[i]) await H.receive(page, M, STOCK[i], places[i].code);
    const all = places.map((p) => p.code);

    for (const reload of [false, true]) {
      if (reload) await page.reload();
      await H.findProduct(page, M);
      // 3 строки, каждая начинается с кода своего места, коды разные
      await expect(H.locBtn(page, M)).toHaveCount(3);
      const codes = await rowCodes(page);
      expect(new Set(codes).size, `разные места в строках: ${codes}`).toBe(3);
      for (const c of codes) expect(all).toContain(c);
      for (const t of await H.locBtn(page, M).allInnerTexts()) expect(t.trim()).toMatch(/^[A-Z]+-\d+ \| קומה 1 \| /);

      // «+2» — кнопка с меню
      await expect(plusBtn(page)).toHaveText('+2');
      await expect(plusBtn(page)).toHaveAttribute('aria-haspopup', 'menu');
      await plusBtn(page).click();
      const items = menu(page).getByRole('menuitem');
      await expect(items).toHaveCount(5);
      for (let i = 0; i < places.length; i++) {
        const it = items.filter({ hasText: places[i].code });
        await expect(it).toHaveCount(1);
        await expect(it).toContainText(new RegExp(`^${places[i].code} · קומה 1 · ארון ${places[i].cabinet} · `));
        if (STOCK[i]) await expect(it).toContainText(`מונחות כאן ${STOCK[i]}`);
        else await expect(it).toContainText('משויך למקום זה, ללא כמות');
      }
      // Esc закрывает
      await page.keyboard.press('Escape');
      await expect(menu(page)).toHaveCount(0);
      // клик вне — закрывает
      await plusBtn(page).click();
      await expect(menu(page)).toBeVisible();
      await page.mouse.click(5, 5); // вне меню (под меню — прозрачная подложка, клик по ней закрывает)
      await expect(menu(page)).toHaveCount(0);
    }
  });

  test('לחיצה על שורה / פריט בתפריט פותחת את חלון «מיקום במחסן» של אותו מקום בלבד #7b8b97e9 @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    test.skip(places.length < 5, 'товар не подготовлен');
    await H.findProduct(page, M);
    const codes = await rowCodes(page);
    const dlg = page.getByRole('dialog');

    // вторая строка колонки
    await H.locBtn(page, M).nth(1).click();
    await expect(dlg.getByRole('heading', { name: 'מיקום במחסן' })).toBeVisible();
    await expect(dlg).toContainText(new RegExp(`המקום הנוכחי(?: \\(\\d+ יחידות\\))?:\\s*[^|]*\\|[^|]*\\|[^|]*\\| ${codes[1]}`));
    for (const c of places.map((p) => p.code).filter((c) => c !== codes[1])) await expect(dlg).not.toContainText(c);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);

    // пункт меню места, которого нет в строках
    const hidden = places.map((p) => p.code).find((c) => !codes.includes(c))!;
    await plusBtn(page).click();
    await menu(page).getByRole('menuitem').filter({ hasText: hidden }).click();
    await expect(dlg.getByRole('heading', { name: 'מיקום במחסן' })).toBeVisible();
    await expect(dlg).toContainText(new RegExp(`המקום הנוכחי(?: \\(\\d+ יחידות\\))?:\\s*[^|]*\\|[^|]*\\|[^|]*\\| ${hidden}`));
    for (const c of places.map((p) => p.code).filter((c) => c !== hidden)) await expect(dlg).not.toContainText(c);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });

  test('«קליטת מלאי»: ב«מקום היעד» רק 5 המקומות של המוצר + «ללא מקום — לשיוך בהמשך» #7b8b97e9 @desktop @data', async ({ page }) => {
    test.skip(places.length < 5, 'товар не подготовлен');
    await H.findProduct(page, M);
    await H.qtyBtn(page, M).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
    const opts = (await dlg.getByRole('combobox', { name: 'מקום היעד' }).locator('option').allInnerTexts()).map((t) => t.trim());
    expect(opts.filter((t) => t !== H.NO_PLACE)).toHaveLength(5);
    expect(opts).toContain(H.NO_PLACE);
    for (const pl of places) expect(opts.some((t) => t.includes(`(${pl.code})`)), `опция ${pl.code}`).toBe(true);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    await expect(H.qtyBtn(page, M)).toHaveText('8'); // ничего не принято
  });

  test('390: «+2» נפתח בלחיצה ומציג 5 מקומות, אין גלילה אופקית של העמוד #7b8b97e9 @desktop @data', async ({ page }) => {
    test.skip(places.length < 5, 'товар не подготовлен');
    await page.setViewportSize({ width: 390, height: 844 });
    await H.findProduct(page, M);
    await plusBtn(page).scrollIntoViewIfNeeded();
    await plusBtn(page).click();
    await expect(menu(page).getByRole('menuitem')).toHaveCount(5);
    await page.keyboard.press('Escape');
    await expect(menu(page)).toHaveCount(0);
    const { sw, iw } = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: window.innerWidth }));
    expect(sw, 'страница без горизонтального скролла').toBeLessThanOrEqual(iw + 1);
  });

  test('מחיקה, 4 מקומות (אחד עם 0): «משויך ל-4 מקומות במחסן, ורשומות בהם עדיין 8.» ו-4 שורות #7b8b97e9 #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    test.skip(places.length < 5, 'товар не подготовлен');
    // убрать одно из мест с 0 → 4 места: 5 / 2 / 1 / 0
    await H.openPlace(page, places[4]);
    await H.unplaceInPanel(page, M);

    await H.findProduct(page, M);
    const del = await H.openRowMenuDelete(page, M);
    await expect(del).toContainText('יש מלאי במחסן');
    await del.click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: H.BLOCK })).toBeVisible({ timeout: 20_000 });
    await expect(dlg).toContainText('— משויך ל-4 מקומות במחסן, ורשומות בהם עדיין 8.');
    const items = dlg.getByRole('listitem');
    await expect(items).toHaveCount(4);
    for (let i = 0; i < 4; i++) {
      const it = items.filter({ hasText: places[i].code });
      await expect(it).toHaveCount(1);
      if (STOCK[i]) await expect(it).toContainText(new RegExp(`${places[i].code}\\s*· ${STOCK[i]}$`));
      else await expect(it).toContainText(new RegExp(`${places[i].code}$`)); // место с 0 — в списке, без количества
    }
    await expect(items.filter({ hasText: places[4].code })).toHaveCount(0);
    await dlg.getByRole('button', { name: 'סגירה' }).click();
    await expect(dlg).toHaveCount(0);
  });
});
